# English versions of the comparison pages (karsilastirma.py). Keys: 'a-b' plant ids.
K_EN = {
'zencefil-zerdecal': dict(baslik='Ginger or turmeric?',
 giris='Ginger and turmeric are two relatives from the same family (Zingiberaceae); in both, the part used is the underground stem (rhizome). They sit side by side in kitchens and on supplement shelves, but their evidence and risks differ.',
 fark=['Ginger’s strongest evidence is for nausea: the European Medicines Agency accepts its use for nausea from motion sickness. Turmeric’s evidence is weaker; there are a few small studies on knee osteoarthritis pain.',
       'Turmeric’s active compound, curcumin, is poorly absorbed; taking it with black pepper and fat increases absorption.',
       'Liver injury has been reported with high-dose turmeric capsules; with ginger, high doses mainly cause heartburn.',
       'Both need care in people on blood thinners and in people with gallstones.'],
 sonuc='For nausea, ginger is the one with evidence. Turmeric is safe as a spice in food; high-dose capsules should not be taken without asking a doctor.'),
'adacayi-dagcayi': dict(baslik='Sage vs mountain tea: what is the difference?',
 giris='In many parts of Anatolia mountain tea is also called “adaçayı” (sage), so the two are often confused. They are plants of different genera: sage is Salvia, mountain tea is Sideritis.',
 fark=['Sage leaves are grey-green and velvety with a sharp smell. Mountain tea is dried with its flowering stems and yellowish flower spikes.',
       'Because sage contains thujone, it should not be drunk for long periods or in large amounts, and is not recommended in pregnancy, breastfeeding or epilepsy. Mountain tea is generally considered safe as a tea.',
       'The European Medicines Agency recognises sage for mouth and throat inflammation, and mountain tea for cough from colds and mild stomach complaints, both as traditional uses.',
       'Some mountain tea species are endemic and over-harvested in the wild; cultivated plants should be preferred.'],
 sonuc='A gargle for the throat is sage’s job. For a tea to drink every day through winter, thujone-free mountain tea is the better fit.'),
'papatya-melisa': dict(baslik='Chamomile or lemon balm? Choosing an evening tea',
 giris='Chamomile and lemon balm are the best-known calming teas drunk in the evening. Both are accepted in Europe for traditional use in mild complaints.',
 fark=['Chamomile is recognised for mild digestive complaints, mouth and throat inflammation and skin irritation; lemon balm for mild stress and sleep problems.',
       'Small studies on anxiety are positive for both, but the evidence is limited.',
       'People allergic to the daisy family should avoid chamomile. Lemon balm needs care in people taking thyroid medication.'],
 sonuc='For restlessness that comes with an upset stomach, chamomile; for the evening after a stressful day, lemon balm. They can also be steeped together.'),
'lavanta-kediotu': dict(baslik='Lavender or valerian? For sleep and anxiety',
 giris='Lavender and valerian are the two herbs most used for sleep and anxiety. The European Medicines Agency recognises both, but their evidence comes in different forms.',
 fark=['For lavender, the strong evidence is for standardised oral lavender oil capsules: they beat placebo for anxiety in several controlled trials. The evidence for lavender tea or scent is not as strong.',
       'Results of sleep studies with valerian root are mixed: some find a small improvement in falling asleep, others find none.',
       'Valerian can cause morning grogginess; it should not be combined with alcohol or sleeping pills, or taken before driving. Lavender capsules can cause burping and nausea.'],
 sonuc='For anxiety, lavender capsules have the stronger evidence. If you struggle to fall asleep, valerian can be tried; neither should be combined with sedatives.'),
'rezene-anason': dict(baslik='Fennel vs anise: what is the difference?',
 giris='Fennel and anise are two similar-smelling seeds from the same family (Apiaceae); both owe their scent to anethole. They are often used together in teas for gas and indigestion.',
 fark=['Fennel seeds are larger and greenish; aniseed is smaller, grey-brown and slightly hairy.',
       'The European Medicines Agency recognises both for mild digestive complaints and gas; fennel also for period pain, anise also for cough from colds.',
       'Because fennel contains estragole, it should not be used long-term by young children or in pregnancy. Concentrated anise oil should not be used in pregnancy or by children.',
       'Both can cause allergy in people allergic to the celery and carrot family.'],
 sonuc='Either is fine for a cup after a meal, and their tastes are very close. Ask a doctor before giving them to babies and young children.'),
'ihlamur-papatya': dict(baslik='Linden or chamomile?',
 giris='Linden and chamomile are the two most popular herbal teas on winter evenings in Türkiye. Both are made by steeping and are generally safe.',
 fark=['Linden is accepted for traditional use in cold symptoms and mild mental stress; there are few clinical studies.',
       'Chamomile is recognised for mild digestive complaints and mouth and throat inflammation; small studies on anxiety are positive.',
       'Chamomile can cause allergy in people allergic to the daisy family; no important risk is known for linden.'],
 sonuc='When you have caught a chill, linden; for an upset stomach, chamomile. Both should be steeped covered, not boiled.'),
'nane-melisa': dict(baslik='Peppermint vs lemon balm: what is the difference?',
 giris='Peppermint and lemon balm belong to the same family (Lamiaceae); their leaves look alike, but their scents are very different: peppermint is cool and sharp, lemon balm smells of lemon.',
 fark=['Peppermint has strong evidence: peppermint oil capsules reduced irritable bowel symptoms in many studies.',
       'Lemon balm is used mostly for mild stress and sleep problems.',
       'Peppermint can worsen reflux, and pure peppermint oil must not be applied to babies’ faces. Lemon balm needs care in people taking thyroid medication.'],
 sonuc='For indigestion and gas, peppermint; for tension, lemon balm.'),
'ekinezya-murver': dict(baslik='Echinacea or elder? For colds',
 giris='Echinacea and elder are two of the best-selling herbal products in cold season. The evidence for both is limited.',
 fark=['Echinacea may slightly prevent or shorten colds, but results are inconsistent.',
       'Elderflower is accepted for traditional use in the early symptoms of a cold; small studies with berry extract are promising but weak.',
       'Raw elderberries, leaves and stems are poisonous; the berries must be cooked. Echinacea needs care in autoimmune disease and in people allergic to the daisy family.'],
 sonuc='Do not expect a big effect from either. If used, start at the first symptoms and use them only briefly.'),
'kekik-adacayi': dict(baslik='Thyme or sage? For cough and sore throat',
 giris='Thyme and sage are the two herbs most often brewed for colds in Anatolia. Both are in the Lamiaceae family and contain strongly scented essential oils.',
 fark=['The European Medicines Agency recognises thyme for productive cough and sage for mouth and throat inflammation, both as traditional uses.',
       'Thyme’s thymol and carvacrol show strong antimicrobial effects in the lab.',
       'Because sage contains thujone, it should not be drunk for long periods or in large amounts. Pure thyme oil burns; it must not be applied to the skin undiluted.'],
 sonuc='For a productive cough, thyme tea; for a sore throat, a sage gargle.'),
'lavanta-karabas': dict(baslik='Lavender vs French lavender (Lavandula stoechas): what is the difference?',
 giris='French lavender (Lavandula stoechas, “karabaş” in Turkish) and true lavender (Lavandula angustifolia) are relatives of the same genus. French lavender grows wild around the Aegean and Mediterranean; what is grown in fields is usually true lavender.',
 fark=['The strong evidence is for true lavender: standardised oil capsules worked for anxiety in several studies. There are very few human studies of French lavender.',
       'Unlike true lavender, French lavender oil contains large amounts of camphor and fenchone; it should not be taken by mouth or applied to children’s faces, because camphor can cause seizures.',
       'French lavender should not be used in pregnancy. True lavender is generally safe but can add to the effect of sedatives.'],
 sonuc='Check which species a “lavender oil” is made from. French lavender tea can be drunk in moderation; its oil should not replace true lavender oil.'),
'kediotu-pasiflora': dict(baslik='Valerian or passionflower?',
 giris='Valerian and passionflower are the two main ingredients of herbal medicines sold in Europe for sleep and anxiety; they are often found in the same tablet.',
 fark=['The European Medicines Agency recognises valerian root for mild nervous tension and sleep problems, and passionflower for mild stress and to help falling asleep.',
       'Studies of passionflower in anxiety and pre-operative nerves are positive but small and short. Results of valerian sleep studies are mixed.',
       'Both can cause drowsiness; they should not be combined with alcohol, sleeping pills or sedatives. Passionflower should not be used in pregnancy.'],
 sonuc='Their evidence is similar and modest. Neither should be taken before driving.'),
'sinameki-keten': dict(baslik='Senna or flaxseed? For constipation',
 giris='Senna and flaxseed work in very different ways. Senna is a stimulant laxative; flaxseed adds bulk to the stool with its fibre and mucilage.',
 fark=['The European Medicines Agency recognises both: senna for short-term treatment of occasional constipation, flaxseed for constipation.',
       'Senna should not be used for more than a week; long-term use causes a lazy bowel and potassium loss. Using it to lose weight is dangerous.',
       'Flaxseed can be used long-term but must always be taken with plenty of water; with too little water it can cause a bowel blockage.'],
 sonuc='For regular use, flaxseed is the suitable one. Senna only briefly and occasionally.'),
# --- 23 November ---
'ginseng-adamotu': dict(baslik='Is ginseng the same as mandrake? Same shape, two plants',
 giris='Both have roots shaped like a human body, which is why both are called “man root” in Turkish folk speech and are often confused. They are completely different plants: ginseng (Panax ginseng) belongs to the ivy family of East Asia, mandrake (Mandragora) to the nightshade family of the Mediterranean. One sits on supplement shelves, the other on lists of poisonous plants.',
 fark=['Ginseng has been used in China and Korea for two thousand years for strength and long life; it contains ginsenosides, and some studies found small effects on blood sugar and immunity. NCCIH says the evidence is limited.', 'The whole mandrake plant is poisonous: its root contains scopolamine and hyoscyamine. That is why it was added to wine as an anaesthetic before surgery in antiquity; the fruit and root can cause hallucinations, heart rhythm disorders and respiratory arrest.', 'Human-shaped roots sold in markets as “aphrodisiacs” are dangerous; preparing or using mandrake is not advised.', 'Ginseng is not harmless either: it can cause insomnia and may interact with blood thinners and diabetes medicines.'],
 sonuc='The Asian ginseng sold as a supplement is not the Mediterranean mandrake. A human-shaped root is not ginseng because of its shape; mandrake should never be taken in any form.'),
'adacayi-akadacayi': dict(baslik='Is sage the same as white sage?',
 giris='Both belong to the genus Salvia and their names are almost the same, but they are used very differently. Anatolian sage (Salvia fruticosa) is brewed and drunk; white sage (Salvia apiana) is the sacred plant that California’s Indigenous peoples burn as incense.',
 fark=['Sage is steeped for 5 minutes as a tea or used as a gargle; the European Medicines Agency recognises it in traditional use for mouth and throat inflammation and excessive sweating.', 'White sage is not prepared for drinking: a bundle of dried leaves is burned and the smoke is wafted. Lab studies show antimicrobial effects; there are no human studies.', 'Because sage contains thujone, it should not be drunk in large amounts for long; it is not advised in pregnancy, breastfeeding or epilepsy. White sage smoke can irritate the airways in closed rooms.', 'Both are under harvesting pressure: most sage sold in Türkiye is wild-collected, and white sage is declining in the wild because of commercial demand.'],
 sonuc='For the throat, the one to drink or gargle is Anatolian sage. White sage is an incense; if you buy it, ask where it comes from, because it is a sacred plant of Indigenous peoples and is declining in the wild.'),
'nane-yarpuz': dict(baslik='Mint or pennyroyal? One scent, two very different risks',
 giris='Pennyroyal is a mint too (Mentha pulegium); it is picked by streams and added to food in place of mint. The two smell alike, but their safety is very different.',
 fark=['Peppermint has some of the strongest evidence in our catalogue: peppermint oil capsules reduced irritable bowel syndrome symptoms compared with placebo in many controlled trials. There are no clinical trials of pennyroyal.', 'Pennyroyal oil is very high in pulegone, which is toxic to the liver and kidneys; deaths have been reported after drinking the oil. Pennyroyal was used throughout history to bring on periods and cause abortion, and this use has killed people.', 'Pennyroyal must never be used in pregnancy; even as a tea it should be drunk only in very small amounts and not for long. Mint is generally safe but may worsen reflux.', 'Pure peppermint oil must not be applied to the faces of babies and small children; it can stop their breathing.'],
 sonuc='For a daily stomach tea or an oil capsule, choose mint. Pennyroyal should stay a small seasoning in food; its essential oil is never swallowed and it is never used in pregnancy.'),
'zakkum-defne': dict(baslik='Oleander or bay laurel? Two trees with look-alike leaves',
 giris='Both are common along the Mediterranean coast and both have long, stiff, glossy green leaves, so the leaves can be confused. One is a kitchen herb; every part of the other is a deadly poisonous ornamental.',
 fark=['Bay leaves go into food and dried leaves are put in cupboards; Hatay’s laurel soap is made from the fruit oil. Kitchen use is safe.', 'Every part of oleander contains cardiac glycosides such as oleandrin that disturb the heart rhythm; even a few leaves are dangerous. Studies of its use for cancer have shown no benefit.', 'Using oleander branches as skewers or barbecue wood can cause poisoning; take care at picnics.', 'Oleander is planted in parks and road verges and has showy pink, white or red flowers; bay flowers are small and yellowish.'],
 sonuc='Never put a leaf from a branch you are unsure of into food or on the barbecue. Oleander must never be prepared or taken; in Türkiye, call the National Poison Information Centre on 114.'),
'cemen-corekotu': dict(baslik='Is fenugreek the same as black seed?',
 giris='The Turkish names sound alike (çemen, çörek otu), but they are two different plants: fenugreek (Trigonella foenum-graecum) is a legume, black seed (Nigella sativa) belongs to the buttercup family. Fenugreek is the base of the spice paste on Turkish pastırma; black seed is sprinkled on pide and cheese.',
 fark=['Fenugreek seeds are yellowish and angular, roasted and ground or soaked; black seeds are small, black and triangular, added whole or cold-pressed for oil.', 'Fenugreek is rich in fibre and saponins; some studies found lower blood sugar, but NCCIH says the evidence is not conclusive. The European Medicines Agency recognises the seed for loss of appetite. Black seed’s active compound is thymoquinone; small studies found slight drops in cholesterol, blood sugar and blood pressure.', 'Fenugreek should not be used in high doses in pregnancy and can cause allergy in people allergic to peanuts or chickpeas.', 'Large amounts of either may strengthen diabetes medicines; fenugreek may also strengthen blood thinners, and black seed oil blood-pressure medicines.'],
 sonuc='In the kitchen, one flavours pastırma and the other pide. If either is taken in medicine-like amounts, people on diabetes medicines should talk to their doctor.'),
'corekotu-kimyon': dict(baslik='Black seed or cumin? The “black cumin” mix-up',
 giris='In many languages black seed is called “black cumin”, which is why it gets confused with cumin. They are from different families: black seed (Nigella sativa) from the buttercups, cumin (Cuminum cyminum) from the carrot family.',
 fark=['Cumin seeds are long, light brown and ridged and flavour meatballs, sausage and bean dishes. Black seeds are small, black and angular and go on bread, buns and cheese.', 'Cumin contains cuminaldehyde, black seed thymoquinone. Cumin has small studies on irritable bowel and weight management; black seed small studies finding slight drops in cholesterol, blood sugar and blood pressure. The evidence is weak for both.', 'Both are safe in food amounts. Above spice amounts, in regular medicine-like use, both may lower blood sugar.', 'Cumin may cause cross-allergy in people allergic to the carrot family (celery, carrot, anise).'],
 sonuc='When a recipe says “black cumin”, it usually means black seed. Cumin is the one to steep for indigestion; black seed is the one sprinkled on bread and cheese.'),
'hatmi-ebegumeci': dict(baslik='Is marshmallow the same as mallow?',
 giris='Both belong to the mallow family (Malvaceae) and are used for the same reason: the mucilage in their tissues coats the throat and stomach. But they are different genera: marshmallow is Althaea officinalis, common mallow Malva sylvestris. Mallow leaves are also eaten as a vegetable.',
 fark=['The European Medicines Agency recognises both in traditional use for mouth and throat irritation and dry cough; with marshmallow the root is used, with mallow the leaves and flowers.', 'Marshmallow root is prepared by soaking in cold water for a few hours, without heat. Mallow can be steeped or soaked; in spring its leaves are sautéed or used for stuffed rolls.', 'In both, the mucilage may delay the absorption of other medicines; leave an hour between them.', 'The English word “marshmallow” comes from this plant: in the 19th century its root mucilage was whipped with sugar to make the first marshmallow sweets.'],
 sonuc='For dry cough and an irritated throat, both do the same job. If you have the root, use marshmallow; if you have leaves and flowers, use mallow. Both are generally safe.'),
'maca-ginseng': dict(baslik='Maca or ginseng? Two roots for strength and energy',
 giris='Both are sold as “roots that give strength”: maca (Lepidium meyenii) is a tuber grown on Peru’s plateaus at 4,000 metres, ginseng (Panax ginseng) the two-thousand-year-old tonic root of East Asia.',
 fark=['Small clinical trials of maca show slight improvements in sexual desire and menopause symptoms; the trials are small and some are funded by manufacturers. Some ginseng studies found small effects on blood sugar and immunity; NCCIH says the evidence is limited.', 'Maca is safe as food; traditionally it is not eaten raw but dried and boiled or eaten as a powder. People with thyroid problems should be careful.', 'Ginseng can cause insomnia and may interact with blood thinners and diabetes medicines.', 'Ginseng is dried or steamed to make “red ginseng” and used as tea or extract.'],
 sonuc='The evidence for both is limited. For someone not on regular medication, maca as a food carries less risk of interactions; anyone on blood thinners or diabetes medicines should not take ginseng without asking their doctor.'),
'tarcin-zencefil': dict(baslik='Cinnamon or ginger? Two warming spices of winter tea',
 giris='Cinnamon is the bark of a tree (Cinnamomum), ginger the underground stem of a plant (Zingiber officinale). Both are said to “warm you up” and to be “good for blood sugar”.',
 fark=['Ginger’s strongest evidence is for nausea: the European Medicines Agency recognises it for preventing motion sickness, and small studies in pregnancy nausea are positive.', 'Cinnamon has many small studies on blood sugar, but the results are inconsistent; NCCIH says there is not enough evidence that it helps any condition.', 'Cassia, the cinnamon most sold in supermarkets, is high in coumarin; eaten by the teaspoon every day it can harm the liver. Ceylon cinnamon contains very little coumarin.', 'Ginger in high doses can cause heartburn; people on blood thinners or with gallstones should ask a doctor before taking supplements.'],
 sonuc='For nausea, ginger is clearly ahead. If you use a lot of cinnamon every day, choose Ceylon cinnamon.'),
'ashwagandha-ginseng': dict(baslik='Ashwagandha or ginseng? Two roots for stress and energy',
 giris='Ashwagandha (Withania somnifera) is the root of Indian Ayurveda, ginseng (Panax ginseng) of Chinese and Korean medicine. Both are sold today as “adaptogens”.',
 fark=['For ashwagandha, a few small, short controlled trials report lower stress and anxiety scores; NCCIH stresses that its long-term safety is unknown.', 'Some ginseng studies found small effects on blood sugar and immunity; the evidence is limited.', 'Ashwagandha has been linked to cases of liver injury, may raise thyroid hormones and carries a risk of miscarriage; some European countries have restricted its supplements.', 'Ginseng can cause insomnia and may interact with blood thinners and diabetes medicines.'],
 sonuc='Ashwagandha sits on the calming side, ginseng on the stimulating side. Anyone on thyroid medication or pregnant should not take ashwagandha, and anyone on blood thinners should not take ginseng, without asking a doctor.'),
'kusburnu-kizilcik': dict(baslik='Rose hip or cornelian cherry? Two sour winter fruits of Anatolia',
 giris='Both are red, sour fruits picked in autumn and made into jams, sherbets and teas. Rose hip (Rosa canina) is from the rose family, cornelian cherry (Cornus mas) from the dogwood family.',
 fark=['Fresh rose hips are very rich in vitamin C; a few clinical trials with rose hip powder looked at knee osteoarthritis pain.', 'Cornelian cherry is rich in anthocyanins and vitamin C; small studies report slight improvements in blood lipids.', 'The hairs around rose hip seeds irritate the mouth and gut; always strain.', 'Cornelian cherry stones are hard and dangerous for small children; its sourness can worsen reflux.'],
 sonuc='Both are safe and local foods. Remember to remove the rose hip hairs and the cornelian cherry stones.'),
'nar-hibiskus': dict(baslik='Pomegranate or hibiscus? Two red drinks for blood pressure',
 giris='Pomegranate juice and hibiscus tea are both deep red and sour, and both are said to “lower blood pressure”.',
 fark=['Several controlled trials and meta-analyses show hibiscus tea slightly lowers blood pressure; the trials are small and short.', 'Small studies also report pomegranate juice slightly lowering blood pressure; claims such as prostate cancer lack evidence.', 'Hibiscus may strengthen blood-pressure medicines; do not drink a lot in pregnancy.', 'Pomegranate juice may affect how some medicines are broken down; the peel and root bark are toxic in high doses.'],
 sonuc='If you take blood-pressure medicine, tell your doctor before drinking either regularly; the evidence for hibiscus is slightly stronger.'),
'sumak-nar': dict(baslik='Sumac or pomegranate molasses? The two sours of the kitchen',
 giris='Both add sourness to salads and kebabs and are staples of south-eastern Turkish cooking. Sumac (Rhus coriaria) is the dried fruit of a shrub; pomegranate molasses is reduced pomegranate (Punica granatum) juice.',
 fark=['Sumac is rich in tannins and organic acids; small clinical studies report slight drops in blood sugar and cholesterol.', 'Pomegranate is rich in polyphenols; small studies report pomegranate juice slightly lowering blood pressure.', 'Sumac may cause cross-allergy in people allergic to cashews or pistachios.', 'Much “pomegranate molasses” on the market is a pomegranate-flavoured sauce of sugar, acid and colouring; choose one whose label lists only pomegranate.'],
 sonuc='Both are safe as food. Buy unsalted sumac and pure pomegranate molasses.'),
'safran-zerdecal': dict(baslik='Saffron or turmeric? Two spices that turn food yellow',
 giris='Saffron (Crocus sativus) is the dried stigmas of a crocus, turmeric (Curcuma longa) the powdered root of a ginger relative. One is the world’s most expensive spice, the other one of the cheapest.',
 fark=['Meta-analyses of small controlled trials show saffron beats placebo in mild to moderate depression; most trials are short and from a single country.', 'Curcumin from turmeric helped knee osteoarthritis pain in some small studies; NCCIH says the evidence for most claims is weak and curcumin is poorly absorbed.', 'Saffron is toxic above 5 g a day and high doses carry a risk of miscarriage; cheap “saffron” is usually safflower or dyed fibre.', 'High-dose turmeric capsules have been linked to cases of liver injury; turmeric may interact with blood thinners, and people with gallstones should be careful.'],
 sonuc='Both are safe in food. Beware fake saffron: real threads colour water yellow slowly.'),
'ayahuasca-sanpedro': dict(baslik='Ayahuasca or San Pedro? Two ceremonies of the Amazon and the Andes',
 giris='Ayahuasca is an Amazonian brew of a vine (Banisteriopsis caapi), usually cooked with chacruna leaves; San Pedro (Echinopsis pachanoi) is a mescaline-containing cactus of the Andes. Both are central to Indigenous healing ceremonies.',
 fark=['The ayahuasca vine contains harmala alkaloids that block MAO-A, which makes the DMT in chacruna active when swallowed. San Pedro’s effect comes from mescaline.', 'Small clinical studies of ayahuasca in depression are promising but early; mescaline has been studied far less than psilocybin and LSD.', 'Ayahuasca can interact fatally with antidepressants and some migraine and heart medicines; deaths and abuse have been reported at unsupervised retreats.', 'San Pedro causes severe nausea, vomiting and a racing heart; it is dangerous for people with heart disease or a history of psychosis.'],
 sonuc='Neither is legal in Türkiye, and neither is something to try at home. This page is for cultural and scientific information.'),
'tatula-banotu': dict(baslik='Jimsonweed or henbane? Two poisonous nightshades',
 giris='Jimsonweed (Datura stramonium) and henbane (Hyoscyamus niger) grow on roadsides and waste ground across Anatolia and carry the same poison. Jimsonweed has a spiny fruit and large white trumpet flowers; henbane has pale yellow flowers with purple veins.',
 fark=['Both contain tropane alkaloids such as atropine, hyoscyamine and scopolamine; their effects are the same.', 'Symptoms: dry mouth, high fever, dilated pupils, hallucinations, racing heart, coma.', 'Jimsonweed has killed teenagers who tried it as a “natural drug”; henbane has poisoned people who picked and ate it by mistake.', 'These alkaloids are the source of today’s medicines for nausea, cramps and eye examinations; but in the plant itself the dose cannot be controlled.'],
 sonuc='Neither has any home use. If you suspect poisoning in Türkiye, call the National Poison Information Centre on 114.'),
}
